package com.ncdex.instrument.config;
import com.ncdex.instrument.document.Instrument;import com.ncdex.instrument.repository.InstrumentRepository;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;
@Configuration public class DataInitializer { @Bean CommandLineRunner seedInstruments(InstrumentRepository repo){return args->{if(repo.count()==0){repo.save(make("GOLD-001","GOLD","Gold","PRECIOUS_METAL",15000));repo.save(make("SILVER-001","SILVER","Silver","PRECIOUS_METAL",180));repo.save(make("CRUDE-001","CRUDEOIL","Crude Oil","ENERGY",6200));repo.save(make("GAS-001","NATGAS","Natural Gas","ENERGY",250));}};} private Instrument make(String id,String symbol,String name,String category,double price){Instrument i=new Instrument();i.setId(id);i.setSymbol(symbol);i.setName(name);i.setCategory(category);i.setIndicativePrice(price);i.setActive(true);return i;} }
